records.command:
$ErrorActionPreference = 'Stop'
$category = '{0CCE9215-69AE-11D9-BED3-505054503030}'
$before = auditpol.exe /get /subcategory:$category
$before
if (($before -join "`n") -notmatch 'Success and Failure') { throw 'Expected initial Success and Failure policy' }
try {
    auditpol.exe /set /subcategory:$category /success:disable
    if ($LASTEXITCODE -ne 0) { throw 'Policy change failed' }
    auditpol.exe /get /subcategory:$category
} finally {
    auditpol.exe /set /subcategory:$category /success:enable
    auditpol.exe /get /subcategory:$category
}
